        "Most Indian children meet hepatitis A subclinically and are immune by adolescence - lifelong antibody is why adult cases stay uncommon. [Park 27e]",
        "**Symptomatic adult hepatitis A is rising** as sanitation improves - first infection is met later, and severity climbs with age at infection. [Park 27e]",
        "Hepatitis E: RNA hepevirus, faeco-oral, incubation **15-60 days** - spread by sewage in piped water, so outbreaks are explosive and communal. [Park 27e]",
        "Hepatitis E causes large water-borne epidemics in India - Kanpur 1991, Delhi 1955-56. [Park 27e]",
        "Hepatitis E is usually self-limiting - no chronic carrier state develops in the immunocompetent, so supportive care is enough. [Harrison 21e]",
        "**Hepatitis E kills 15-25% in the third trimester** - pregnancy shifts immunity and hormones towards fulminant hepatic failure. [Park 27e]",
        "Hepatitis E genotype 3 turns chronic in transplant recipients - weak T-cell clearance lets it persist, so reduce immunosuppression. [Harrison 21e]",
        "Hepatitis B: DNA hepadnavirus, incubation **45-180 days** - the long silent window is why needle-stick follow-up runs for months. [Harrison 21e]",
        "Hepatitis B spreads blood-borne, sexually and perinatally - far more infectious per exposure than HIV, so universal precautions are not optional. [Park 27e]",
