        "**55-85% of hepatitis C infections become chronic** - the virus escapes antibody, so every anti-HCV positive patient needs an RNA test. [WHO HCV 2022]",
        "Punjab, Haryana and the north-east carry most of India's hepatitis C - unsafe injection practice and injecting drug use, so screen locally. [NVHCP 2018]",
        "**Hepatitis D** is a defective RNA virus needing HBsAg to replicate - it cannot infect anyone already protected by hepatitis B vaccine. [Harrison 21e]",
        "Hepatitis D co-infection with B is usually self-limiting - both viruses go when the acute hepatitis B resolves. [Harrison 21e]",
        "**Hepatitis D superinfection of a chronic carrier** causes severe hepatitis - delta finds unlimited HBsAg, so cirrhosis is accelerated. [Harrison 21e]",
        "**A and E never become chronic** in the immunocompetent - no antiviral and no long-term follow-up are needed once recovery is complete. [Harrison 21e]",
        "**B, C and D do become chronic** - each must be sought and treated, as silent fibrosis runs on for decades before it declares itself. [Harrison 21e]",
