        "**Acute mesenteric ischaemia has pain grossly out of proportion to the signs** and is a catastrophe, not a colitis. [ACG 2023]",
        "**Colonoscopy after bowel preparation is the investigation of choice**, usually within 24 hours for major bleeding. [ACG 2023]",
        "**CT angiography is used when bleeding is brisk and ongoing** - it detects rates above 0.3-0.5 mL/min and is followed by embolisation. [ACG 2023]",
