        "**A Glasgow-Blatchford score of 2 or more is admitted** - the score exists to identify the few who need not be. [ACG 2021]",
        "**A clinic without blood banking and endoscopy stabilises and transfers rather than observes** - observing without the means to treat is not management. [ACG 2021]",
