        "**It also detects dyssynergic defecation - paradoxical contraction, or failure to relax the puborectalis and external sphincter on simulated straining**. [AGA 2023]",
        "**Dyssynergia is present in up to half of refractory cases and needs biofeedback, not more laxatives** - that is why the finger matters. [AGA 2023]",
