        "**Soluble fibre such as ispaghula or isabgol helps, whereas insoluble bran worsens pain and bloating** - a favourite exam distinction. [AGA 2023]",
        "**A low FODMAP diet helps about 50-70 percent of patients** - fermentable oligosaccharides, disaccharides, monosaccharides and polyols. [AGA 2023]",
        "**Restrict FODMAPs for only 4-6 weeks under a dietitian, then reintroduce systematically** - long-term restriction harms microbiota and nutrition. [AGA 2023]",
        "In India the elimination phase means limiting **wheat, rajma and chana, onion, garlic, milk, apples and mangoes**. [INASL 2023]",
        "For pain and bloating: **mebeverine 135 mg three times daily, dicyclomine 10-20 mg, or hyoscine butylbromide 10 mg, taken before meals**. [AGA 2023]",
